ul:
{{- range split .Inner "\n" }}
  {{- $line := strings.TrimSpace . }}
  {{- if and $line (in $line "|") }}
    {{- $p := split $line "|" }}

Bytes {{ index $p 0 | strings.TrimSpace }}: {{ index $p 1 | strings.TrimSpace }}{{ with index $p 2 | strings.TrimSpace }}. {{ . }}{{ end }}
  {{- end }}
{{- end }}
